SELECT p.gender, d.drug_class, SUM(CASE WHEN h.intime BETWEEN a.admittime AND a.admittime + INTERVAL '12 hours' THEN 1 ELSE 0 END)::FLOAT / NULLIF(SUM(CASE WHEN h.intime BETWEEN (a.dischtime - INTERVAL '48 hours') AND a.dischtime THEN 1 ELSE 0 END), 0) AS proportion FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN pharmacy ph ON a.subject_id = ph.subject_id JOIN poe po ON ph.poe_id = po.poe_id JOIN prescriptions pr ON po.poe_id = pr.poe_id JOIN d_items d ON pr.itemid = d.itemid JOIN chartevents h ON a.subject_id = h.subject_id AND a.hadm_id = h.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 69 AND p.anchor_year_group BETWEEN 64 AND 74 AND d.drug_class IN ('insulin', 'metformin', 'sulfonylureas', 'DPP-4', 'SGLT2', 'GLP-1', 'TZDs') GROUP BY p.gender, d.drug_class;